@section('scripts')
<script>
const questionData={@foreach($questions as $q){{ $q->id }}:{qid:@json($q->question_id),text:@json($q->question_text),correct:@json($q->correct_answer),explanation:@json($q->explanation),difficulty:@json($q->difficulty),tags:@json($q->tags),image:@json($q->image_url),status:{{ $q->status?'true':'false' }},category:@json($q->category_id),topic:@json($q->topic_id),type:@json($q->question_type),options:@json($q->options??[])}@if(!$loop->last),@endif @endforeach};
function filterEditTopics(){const cat=document.getElementById('eqCategory').value,topic=document.getElementById('eqTopic');Array.from(topic.options).forEach(o=>{if(!o.value)return;o.hidden=!!cat&&o.dataset.category!==cat;if(o.hidden&&o.selected)topic.value='';});}
document.getElementById('eqCategory').addEventListener('change',filterEditTopics);
function editQ(id){const q=questionData[id];if(!q)return;document.getElementById('editQForm').action='/admin/test-engine/questions/'+id;document.getElementById('eqId').value=q.qid||'';document.getElementById('eqText').value=q.text;document.getElementById('eqCorrect').value=q.correct;document.getElementById('eqExplain').value=q.explanation||'';document.getElementById('eqDifficulty').value=q.difficulty;document.getElementById('eqTags').value=q.tags||'';document.getElementById('eqImage').value=q.image||'';document.getElementById('eqStatus').checked=q.status;document.getElementById('eqCategory').value=q.category||'';filterEditTopics();document.getElementById('eqTopic').value=q.topic||'';document.getElementById('eqType').value=q.type;const wrap=document.getElementById('eqOptions');wrap.innerHTML='';if(q.type==='mcq'){['A','B','C','D'].forEach((label,i)=>{const div=document.createElement('div'),lab=document.createElement('label'),input=document.createElement('input');lab.textContent='Option '+label;input.name='options[]';input.value=(q.options||[])[i]||'';if(i<2)input.required=true;div.append(lab,input);wrap.append(div);});wrap.style.display='grid';}else{wrap.style.display='none';}openModal('editQ');}
</script>
@endsection
